function softMatch(t){
  const words = t.split(/[^a-z0-9$']+/).filter(Boolean);
  let bestId=null, best=0;
  for(const id in SOFT){
    let sc=0;
    for(const k of SOFT[id]){
      if(k.length<5 ? words.includes(k) : (words.includes(k) || t.includes(k))) sc++;
    }
    if(sc>best){ best=sc; bestId=id; }
  }
  return best>0 ? bestId : null;
}

function catchAll(text){
  return `Let me get you to the right person for that one — I'd rather connect you to someone who knows than guess and get it wrong.

<ul>
<li><strong>Connect with Admin</strong> — for anything account or platform specific</li>
<li><strong>The Q&amp;A forum</strong> — other providers answer there</li>
<li><strong>NDIA on 1800 800 110</strong> — for anything official about the scheme itself</li>
</ul>
Try me another way too — a different wording often lands, and I'd rather have a go than send you away empty-handed.

Meanwhile, these I can definitely help with:`;
}

